typedef unsigned int nlUint32;
typedef unsigned int nslSoundId;

enum _nslClearBehaviour
{
  NSL_CLEAR_INIT,
  NSL_CLEAR_RESET,
  NSL_CLEAR_FREE,
};

template <class T>
class fifo_queue
{
  T *queue;
  short queue_max;
  short start;
  short end;
  short count;

public:
  void init(short size);
  void clear();
  void free();
};

struct nslSystem
{
  float listenerPo[4][4];
  char slots[0x15800];
  nlUint32 sourceSlotsUsedCount;
  nlUint32 soundSlotsUsedCount;
  nlUint32 emitterSlotsUsedCount;
  int firstInit;
  int initialized;
  nlUint32 numBanks;
  fifo_queue<nslSoundId> queuedSounds;
};

extern nslSystem nsl;
extern void nlIdentityMatrix(float matrix[4][4]) __asm__("nlIdentityMatrix__FPA3_f");
extern void _nslClearSourceSlot(nlUint32 whichSlot, bool resetId);
extern void _nslClearSoundSlot(nlUint32 whichSlot, bool resetId);
extern void _nslClearEmitterSlot(nlUint32 whichSlot, bool resetId, _nslClearBehaviour clearStyle);

void _nslClearSystemData(_nslClearBehaviour clearStyle)
{
  int i;

  nlIdentityMatrix(nsl.listenerPo);
  switch (clearStyle)
  {
    case NSL_CLEAR_INIT:
      nsl.queuedSounds.init(64); break;
    case NSL_CLEAR_RESET:
      nsl.queuedSounds.clear(); break;
    case NSL_CLEAR_FREE:
      nsl.queuedSounds.free(); break;
  }

  nsl.queuedSounds.clear();

  nsl.sourceSlotsUsedCount = 0;
  nsl.soundSlotsUsedCount = 0;
  nsl.emitterSlotsUsedCount = 0;

  for (i = 0; i < 512; ++i)
    _nslClearSourceSlot(i, true);
  for (i = 0; i < 256; ++i)
    _nslClearSoundSlot(i, true);
  for (i = 0; i < 256; ++i)
    _nslClearEmitterSlot(i, true, clearStyle);
}
